import{_ as i,C as e,o as n,c as l,j as a,a as d,E as o,a2 as p}from"./chunks/framework.B-bxTAy7.js";const x=JSON.parse('{"title":"寄存器映射","description":"内存映射 I/O 的含义、Cortex-M 的地址空间划分、偏移表与寄存器结构的读法。","frontmatter":{"title":"寄存器映射","description":"内存映射 I/O 的含义、Cortex-M 的地址空间划分、偏移表与寄存器结构的读法。"},"headers":[],"relativePath":"prereq/register-map.md","filePath":"prereq/register-map.md","lastUpdated":1792474335000}'),r={name:"prereq/register-map.md"};function c(h,s,k,g,m,y){const t=e("Meta");return n(),l("div",null,[s[0]||(s[0]=a("h1",{id:"寄存器映射",tabindex:"-1"},[d("寄存器映射 "),a("a",{class:"header-anchor",href:"#寄存器映射","aria-label":'Permalink to "寄存器映射"'},"​")],-1)),o(t,{time:"5 min",level:"卡片",note:"偏移量单位是字节，不是「第几个寄存器」；写错不报错，只是行为诡异"}),s[1]||(s[1]=p(`<p><strong>「配置外设」就是往固定地址写特定的数——寄存器是占着固定地址的一小块内存，不是某种特殊硬件。</strong></p><h2 id="记住这几条" tabindex="-1">记住这几条 <a class="header-anchor" href="#记住这几条" aria-label="Permalink to &quot;记住这几条&quot;">​</a></h2><ul><li>「配置外设」的本质是<strong>往固定地址写特定的数</strong>。寄存器不是某种特殊硬件，而是<strong>占据固定地址的一小块内存</strong>。</li><li>Cortex-M 有 4 GB 线性地址空间，厂商把它切成：Flash（代码与 <code>const</code>）、SRAM（变量、栈、堆）、<strong>外设寄存器区</strong>、内核系统控制块（NVIC、SysTick）。</li><li>外设寄存器按<strong>基地址 + 固定偏移</strong>排列，偏移量写在手册里（通常是 4 的倍数）。</li><li>CMSIS（Cortex 微控制器软件接口标准）把这些地址定义成<strong>结构体指针</strong>，于是 <code>GPIOA-&gt;ODR |= (1&lt;&lt;5)</code> 这种写法，本质是往 <code>0x4001080C</code> 写一个数。</li><li>三个动作各归其位：<strong>读-改-写</strong>改寄存器位，<strong>置位/清零</strong>用 <code>BSRR</code> 原子完成，<strong>配引脚模式</strong>用 <code>CRL/CRH</code>。</li><li>寄存器字段常常是<strong>位段</strong>（一个 32 位字里挤着十几个互不相干的配置位），所以位操作是基本功而不是技巧。</li></ul><p><strong>为什么它承重</strong>：嵌入式和上位的分水岭就在这里——没有「内存」这个概念，就没法理解指针、地址、<code>volatile</code>、原子性，也没法写出第一行驱动代码。</p><h2 id="典型数值" tabindex="-1">典型数值 <a class="header-anchor" href="#典型数值" aria-label="Permalink to &quot;典型数值&quot;">​</a></h2><p>以 F103 的 GPIOA 为例，寄存器组从 <code>0x4001 0800</code> 开始：</p><table tabindex="0"><thead><tr><th>偏移</th><th>寄存器</th><th>作用</th></tr></thead><tbody><tr><td><code>0x00</code></td><td><code>CRL</code></td><td>配置 Pin0~7（每脚 4 位）</td></tr><tr><td><code>0x04</code></td><td><code>CRH</code></td><td>配置 Pin8~15（每脚 4 位）</td></tr><tr><td><code>0x08</code></td><td><code>IDR</code></td><td>输入数据（读引脚电平）</td></tr><tr><td><code>0x0C</code></td><td><code>ODR</code></td><td>输出数据（写引脚电平）</td></tr><tr><td><code>0x10</code></td><td><code>BSRR</code></td><td><strong>原子</strong>置位/清零</td></tr><tr><td><code>0x14</code></td><td><code>BRR</code></td><td>清零（等价于 BSRR 高 16 位）</td></tr></tbody></table><p>CMSIS 把这张表变成一个结构体指针，于是下面两行完全等价：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GPIOA_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40010800</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UL</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  volatile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CRL, CRH, IDR, ODR, BSRR, BRR, LCKR;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} GPIO_TypeDef;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GPIOA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((GPIO_TypeDef </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)GPIOA_BASE)</span></span></code></pre></div><ul><li>地址区间速记：Flash <code>0x0800 0000</code>~、SRAM <code>0x2000 0000</code>~、外设 <code>0x4000 0000</code>~、内核 <code>0xE000 0000</code>~。</li><li>32 位寄存器里常塞十几个字段，<strong>一个 32 位字 = 4 个字节 = 4 个外设寄存器</strong>——按字节偏移时别把 <code>0x04</code> 写成 <code>0x01</code>。</li><li>指针加 1 走的是<strong>下一个 32 位寄存器</strong>，不是下一个字节：<code>(uint32_t *)0x40010800 + 1</code> 落在 <code>0x40010804</code>（CRH），不是 <code>0x40010801</code>。</li><li>结构体里的 <code>volatile</code> 不是装饰：没有它，编译器会把「读一次、算一次、写回」优化掉，改配置就完全失效。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>偏移量写错单位</strong>：手册给的是字节偏移，不是「第几个寄存器」。</li><li>忘记使能外设时钟就写寄存器：写进去了，硬件不响应（见<a href="./clock-tree">时钟树</a>）。</li><li><strong>「读-改-写」不是原子的</strong>：在中断里可能被抢占，必须用 <code>BSRR</code>。</li><li>用 <code>ODR</code> 直接改引脚电平时忘了先配 <code>CRL/CRH</code> 的模式位（推挽/开漏、上下拉、速度）。</li><li>把结构体指针强转成 <code>uint32_t*</code> 逐个访问：结构体的对齐与打包假设可能不成立。</li><li><strong>地址算完不核对用途</strong>：<code>0x4000 0000</code> 起的整段都是外设区，不同外设的基地址彼此独立，抄错一位就会写到别的外设上——而且<strong>不报错</strong>，只是行为诡异。</li></ul><div class="tip custom-block" id="ex-register-map-1"><p class="custom-block-title">例 1 · 用偏移算出 GPIOA 的 ODR 地址</p><p>F103 的 GPIOA 基地址是 <code>0x4001 0800</code>，ODR 偏移 <code>0x0C</code>。</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>0</mn><mi>x</mi><mn>40010800</mn><mo>+</mo><mn>0</mn><mi>x</mi><mn>0</mn><mi>C</mi><mo>=</mo><mn>0</mn><mi>x</mi><mn>4001080</mn><mi>C</mi></mrow><annotation encoding="application/x-tex">0x40010800 + 0x0C = 0x4001080C </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0</span><span class="mord mathnormal">x</span><span class="mord">40010800</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0</span><span class="mord mathnormal">x</span><span class="mord">0</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0</span><span class="mord mathnormal">x</span><span class="mord">4001080</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span></span><p>于是把 PA5 置 1，写的就是这个地址上的第 5 位：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPIOA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ODR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 即向 0x4001080C 写 OR 后的 32 位数</span></span></code></pre></div><p>要原子地置位（可能正在中断里），改用 <code>BSRR</code>（偏移 <code>0x10</code>）：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPIOA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BSRR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 置位；清零则写 GPIOA-&gt;BSRR = (1 &lt;&lt; 21)</span></span></code></pre></div><blockquote><p><strong>为什么这么想</strong> 「寄存器」这个词容易让人以为它是某种独立的硬件机制，其实它就是内存。把寄存器想成内存，普通 C 的指针、<code>volatile</code>、位运算就全都对得上了——<code>ODR</code> 是内存中的一个 32 位字，和读一个变量没有本质区别。</p></blockquote></div><blockquote><p>深入：完整内容见 <a href="./../embedded/embedded-c">03 · 嵌入式 C 与寄存器思维</a></p></blockquote>`,14))])}const C=i(r,[["render",c]]);export{x as __pageData,C as default};
